@push('scripts')<script>(()=>{const type=document.querySelector('[data-package-type]'),dims=document.querySelector('[data-dimensions]'),addresses=document.querySelector('[data-addresses]');const sync=()=>{const box=type?.value==='caja';dims.hidden=!box;dims.querySelectorAll('input').forEach(input=>input.required=box)};type?.addEventListener('change',sync);sync();document.querySelectorAll('[data-postal]').forEach(input=>input.addEventListener('change',async()=>{const side=input.dataset.postal,select=document.querySelector(`[data-settlement="${side}"]`),location=document.querySelector(`[data-location="${side}"]`);addresses.classList.add('is-visible');select.disabled=true;select.innerHTML='<option value="">Consultando catálogo…</option>';location.textContent='';if(!/^\d{5}$/.test(input.value)){select.innerHTML='<option value="">Captura un código postal válido</option>';return}try{const response=await fetch(`/codigos-postales/${input.value}`,{headers:{Accept:'application/json'}}),data=await response.json();if(!response.ok)throw new Error(data.message);select.innerHTML='<option value="">Selecciona una colonia</option>'+data.colonias.map(c=>`<option>${c.nombre}</option>`).join('');select.disabled=false;select.required=true;location.textContent=`${data.municipio}, ${data.estado}`}catch(e){select.innerHTML='<option value="">Catálogo temporalmente no disponible</option>';location.textContent=e.message||'No fue posible consultar el catálogo'}}));document.querySelector('[data-landing-tracking]')?.addEventListener('submit',event=>{event.preventDefault();const value=event.currentTarget.elements.tracking.value.trim();if(value)location.href='/rastreo/'+encodeURIComponent(value)});if(document.querySelector('.z-alert--danger')||@json((bool)old('cp_origen')))addresses.classList.add('is-visible');@if($result ?? null)document.querySelector('#resultados')?.scrollIntoView({behavior:'smooth'})@endif})()</script>@endpush
